static unsigned long cases;
static int check(const name_map *names, unsigned count, const uint16_t *index, unsigned mask, cs_arch arch, const char *text) {
    cs_struct handle = {0}; cs_insn a = {0}, b = {0}; MCInst mi = {0}; SStream ss = {0};
    handle.arch = arch; mi.csh = &handle; mi.flat_insn = &a; mi.isAliasInstr = true;
    strcpy(ss.buffer,text); baseline(&mi,&ss,names,count);
    mi.flat_insn = &b; map_set_alias_id_indexed(&mi,&ss,names,index,mask);
    ++cases;
    if (memcmp(&a, &b, sizeof(a))) { fprintf(stderr,"Alias mismatch arch=%u text=%s expected=%llu actual=%llu\n",arch,text,(unsigned long long)a.alias_id,(unsigned long long)b.alias_id); return 1; }
    return 0;
}
static int fixture(const name_map *names, unsigned count, const uint16_t *index, unsigned mask) {
    const cs_arch arches[] = {CS_ARCH_MIPS,CS_ARCH_PPC,CS_ARCH_AARCH64,CS_ARCH_RISCV,CS_ARCH_SPARC,CS_ARCH_ARM};
    const char *suffixes[] = {"", " r0", "\tr0", ".suffix", ",pt r0", "_suffix"};
    char text[512];
    for (unsigned a=0;a<sizeof(arches)/sizeof(arches[0]);++a) {
        for (unsigned i=0;i<count;++i) {
            if (!names[i].name) continue;
            for (unsigned s=0;s<sizeof(suffixes)/sizeof(suffixes[0]);++s) {
                snprintf(text,sizeof(text)," \t%s%s",names[i].name,suffixes[s]);
                if (check(names,count,index,mask,arches[a],text)) return 1;
            }
            size_t n=strlen(names[i].name);
            for (size_t j=0;j<n;++j) {
                strcpy(text,names[i].name); text[j]=0;
                if (check(names,count,index,mask,arches[a],text)) return 1;
                for (unsigned c=1;c<256;++c) {
                    strcpy(text,names[i].name); text[j]=(char)c;
                    if (check(names,count,index,mask,arches[a],text)) return 1;
                }
            }
        }
    }
    MCInst mi={0}; cs_insn insn={0}; mi.flat_insn=&insn; insn.alias_id=99;
    map_set_alias_id_indexed(&mi,NULL,NULL,NULL,~0u);
    return insn.alias_id != 0;
}
int main(int argc,char **argv) {
 if(argc!=2)return 2;
 void *lib=dlopen(argv[1],RTLD_NOW|RTLD_LOCAL);
 if(!lib || !(baseline=(void (*)(MCInst *,const SStream *,const name_map *,int))dlsym(lib,"map_set_alias_id")))return 2;
 if(fixture(names_Mips,ARR_SIZE(names_Mips),slots_Mips,ARR_SIZE(slots_Mips)-1)) return 1;
 if(fixture(names_ARM,ARR_SIZE(names_ARM),slots_ARM,ARR_SIZE(slots_ARM)-1)) return 1;
 if(fixture(names_AArch64,ARR_SIZE(names_AArch64),slots_AArch64,ARR_SIZE(slots_AArch64)-1)) return 1;
 if(fixture(names_Sparc,ARR_SIZE(names_Sparc),slots_Sparc,ARR_SIZE(slots_Sparc)-1)) return 1;
 printf("Verified %lu complete ARM/AArch64/MIPS/SPARC indexed alias states against the reference library\n",cases);return 0;
}
